/** Safari/Chrome paint a solid black PNG when canvas pixels exceed ~16M. */
export const MAX_CANVAS_PIXELS = 12_000_000;
export const MAX_CANVAS_SIDE = 8192;

/**
 * Pick an html2canvas scale that stays under browser canvas limits.
 * Must be allowed below 1 — a 7-day / 5-court card at scale 2 already exceeds Safari.
 */
export function computeExportScale(width, height, preferred = 2) {
  if (!(width > 0) || !(height > 0)) return 1;
  const byArea = Math.sqrt(MAX_CANVAS_PIXELS / (width * height));
  const scale = Math.min(
    preferred,
    MAX_CANVAS_SIDE / width,
    MAX_CANVAS_SIDE / height,
    byArea
  );
  return Math.max(0.25, Math.round(scale * 100) / 100);
}
