import React, { useMemo, useRef, useState, useCallback, useEffect, useLayoutEffect } from "react";
import { Download, Loader2 } from "lucide-react";
import html2canvas from "html2canvas";
import toast from "react-hot-toast";
import config from "../../../config";
import { formatHourAmpm, resolveHourStatus, POST_STATUS } from "./calendarUtils";
import { computeExportScale } from "./postExport";

function buildRollingDays(startDate, count = 7) {
  const days = [];
  const start = new Date(startDate);
  start.setHours(0, 0, 0, 0);
  for (let i = 0; i < count; i += 1) {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    days.push(d);
  }
  return days;
}

/** Wait for images inside the export root to finish loading. */
function waitForImages(root) {
  const imgs = Array.from(root.querySelectorAll("img"));
  return Promise.all(
    imgs.map(
      (img) =>
        new Promise((resolve) => {
          if (img.complete && img.naturalWidth > 0) {
            resolve();
            return;
          }
          img.onload = () => resolve();
          img.onerror = () => resolve();
        })
    )
  );
}

function patchStyle(el, patch) {
  const prev = {};
  Object.keys(patch).forEach((key) => {
    prev[key] = el.style[key];
    el.style[key] = patch[key];
  });
  return prev;
}

function restoreStyle(el, prev) {
  Object.keys(prev).forEach((key) => {
    el.style[key] = prev[key];
  });
}

function isCanvasMostlyBlack(canvas) {
  try {
    const ctx = canvas.getContext("2d");
    if (!ctx) return false;
    const w = canvas.width;
    const h = canvas.height;
    if (w < 8 || h < 8) return true;
    const points = [
      [Math.floor(w * 0.5), Math.floor(h * 0.45)],
      [Math.floor(w * 0.25), Math.floor(h * 0.55)],
      [Math.floor(w * 0.75), Math.floor(h * 0.6)],
      [Math.min(12, w - 1), Math.min(12, h - 1)],
    ];
    return points.every(([x, y]) => {
      const d = ctx.getImageData(x, y, 1, 1).data;
      return d[0] < 8 && d[1] < 8 && d[2] < 8 && d[3] > 200;
    });
  } catch {
    return false;
  }
}

async function rasterizePostCard(source, width, height, scale) {
  const rect = source.getBoundingClientRect();
  return html2canvas(source, {
    backgroundColor: "#F5F7FF",
    scale,
    useCORS: true,
    allowTaint: false,
    logging: false,
    width,
    height,
    windowWidth: width,
    windowHeight: height,
    x: 0,
    y: 0,
    scrollX: -rect.left,
    scrollY: -rect.top,
    onclone: (_doc, el) => {
      el.style.transform = "none";
      el.style.maxWidth = "none";
      el.style.overflow = "visible";
      const clonedScroll = el.querySelector("[data-post-scroll]");
      if (clonedScroll) {
        clonedScroll.style.overflow = "visible";
        clonedScroll.style.maxWidth = "none";
      }
      el.querySelectorAll(".sticky").forEach((node) => {
        node.style.position = "static";
        node.style.left = "auto";
        node.style.zIndex = "auto";
      });
    },
  });
}

/** Capture the post card. In-place, unclipped, with a canvas-size-safe scale. */
async function capturePostCardPng(source) {
  await waitForImages(source);

  const saved = [];
  const save = (el, patch) => {
    if (!el) return;
    saved.push({ el, prev: patchStyle(el, patch) });
  };

  let parent = source.parentElement;
  while (parent) {
    save(parent, { overflow: "visible", overflowX: "visible", overflowY: "visible" });
    parent = parent.parentElement;
  }
  [document.body, document.documentElement].forEach((el) => {
    save(el, { overflow: "visible", height: "auto" });
  });

  const scroll = source.querySelector("[data-post-scroll]");
  const table = source.querySelector("table");

  save(source, {
    maxWidth: "none",
    width: "max-content",
    transform: "none",
    position: "relative",
  });

  const card = source.querySelector("[data-post-card]");
  save(card, { overflow: "visible" });

  if (scroll) {
    save(scroll, {
      overflow: "visible",
      width: `${scroll.scrollWidth}px`,
      maxWidth: "none",
    });
  }

  source.querySelectorAll(".sticky").forEach((el) => {
    save(el, { position: "static", left: "auto", zIndex: "auto" });
  });

  if (table) {
    const tableWidth = scroll?.scrollWidth || table.scrollWidth;
    save(table, {
      width: `${tableWidth}px`,
      minWidth: `${tableWidth}px`,
    });
  }

  const logo = source.querySelector("img");
  let logoPrevSrc = null;
  if (logo?.src && !logo.src.startsWith("data:")) {
    try {
      const resp = await fetch(logo.src);
      const blob = await resp.blob();
      const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
      });
      logoPrevSrc = logo.src;
      logo.src = dataUrl;
      await waitForImages(source);
    } catch {
      // Logo stays as-is; export may still succeed without it
    }
  }

  source.scrollIntoView({ block: "start", inline: "nearest" });
  await new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(resolve));
  });

  const width = Math.ceil(source.scrollWidth);
  const height = Math.ceil(source.scrollHeight);

  if (width < 16 || height < 16) {
    throw new Error("Export area is empty");
  }

  try {
    let scale = computeExportScale(width, height, 2);
    let canvas = await rasterizePostCard(source, width, height, scale);

    if (isCanvasMostlyBlack(canvas) && scale > 1) {
      canvas = await rasterizePostCard(source, width, height, 1);
    }

    if (isCanvasMostlyBlack(canvas)) {
      throw new Error("Export rendered blank");
    }

    const dataUrl = canvas.toDataURL("image/png");
    if (!dataUrl || dataUrl === "data:," || dataUrl.length < 100) {
      throw new Error("Export produced an empty PNG");
    }
    return dataUrl;
  } finally {
    if (logo && logoPrevSrc) {
      logo.src = logoPrevSrc;
    }
    saved.reverse().forEach(({ el, prev }) => restoreStyle(el, prev));
  }
}

export default function CalendarPostView({
  courts = [],
  bookings = {},
  slots = [],
  openHour = 8,
  closeHour = 24,
  startDate = new Date(),
  dayCount = 7,
}) {
  const captureRef = useRef(null);
  const previewRef = useRef(null);
  const [isExporting, setIsExporting] = useState(false);
  const [fitScale, setFitScale] = useState(1);
  const [contentHeight, setContentHeight] = useState(0);
  const days = useMemo(() => buildRollingDays(startDate, dayCount), [startDate, dayCount]);

  const hours = useMemo(() => {
    const list = [];
    for (let h = openHour; h < closeHour; h += 1) list.push(h);
    return list;
  }, [openHour, closeHour]);

  const rangeLabel = useMemo(() => {
    const first = days[0];
    const last = days[days.length - 1];
    const fmt = (d) =>
      d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
    return `${fmt(first)} – ${fmt(last)}, ${first.getFullYear()}`;
  }, [days]);

  const statusStyles = {
    available: "bg-[#7ED321]/15 text-[#4a8c14] border-[#7ED321]/40",
    booked: "bg-[#2F55FF]/15 text-[#1e3dcc] border-[#2F55FF]/50",
    unavailable: "bg-[#0B102E]/10 text-[#0B102E]/70 border-[#0B102E]/25",
  };

  // ~80px per hour chip × 4 cols + gaps + padding
  const courtColMinWidth = 320;
  const tableMinWidth = Math.max(800, 160 + courts.length * courtColMinWidth);
  const naturalWidth = tableMinWidth + 64;

  const updateFitScale = useCallback(() => {
    const preview = previewRef.current;
    if (!preview) return;
    const available = preview.clientWidth;
    if (available <= 0) return;
    setFitScale(Math.min(1, available / naturalWidth));
  }, [naturalWidth]);

  useLayoutEffect(() => {
    updateFitScale();
  }, [updateFitScale, dayCount, courts.length, tableMinWidth]);

  useEffect(() => {
    const preview = previewRef.current;
    if (!preview) return undefined;

    const ro = new ResizeObserver(updateFitScale);
    ro.observe(preview);
    window.addEventListener("resize", updateFitScale);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", updateFitScale);
    };
  }, [updateFitScale]);

  useEffect(() => {
    const source = captureRef.current;
    if (!source) return undefined;

    const measure = () => setContentHeight(source.offsetHeight);
    measure();

    const ro = new ResizeObserver(measure);
    ro.observe(source);
    return () => ro.disconnect();
  }, [dayCount, courts.length, tableMinWidth, days.length, hours.length]);

  const renderHourChip = (courtId, dateYmd, hour) => {
    const { kind } = resolveHourStatus({
      slots,
      bookings,
      courtId,
      dateYmd,
      hour,
    });
    return (
      <div
        key={hour}
        className={`rounded-lg px-2.5 py-2.5 border-2 text-center leading-snug post-hour-cell min-h-[52px] flex flex-col items-center justify-center ${statusStyles[kind]}`}
      >
        <div className="text-xs font-semibold post-hour-time whitespace-nowrap">
          {formatHourAmpm(hour).replace(" ", "")}
        </div>
        <div className="text-[11px] font-bold post-hour-status mt-1">
          {POST_STATUS[kind].short}
        </div>
      </div>
    );
  };

  const handleDownloadPng = useCallback(async () => {
    const source = captureRef.current;
    if (!source || isExporting) return;

    setIsExporting(true);
    source.setAttribute("data-exporting", "true");

    try {
      await new Promise((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(resolve));
      });

      const dataUrl = await capturePostCardPng(source);

      const slug = config.clientKey || "courts";
      const dateStr = days[0].toLocaleDateString("en-CA");
      const link = document.createElement("a");
      link.download = `${slug}-availability-${dateStr}-${dayCount}d.png`;
      link.href = dataUrl;
      link.click();
      toast.success("PNG downloaded");
    } catch (err) {
      console.error("Post PNG export failed", err);
      toast.error("Could not export PNG. Try again.");
    } finally {
      source.removeAttribute("data-exporting");
      setIsExporting(false);
    }
  }, [days, dayCount, isExporting]);

  return (
    <div className="min-h-full bg-[#F5F7FF] p-4 md:p-8 overflow-x-hidden overflow-y-auto">
      <style>{`
        [data-post-export-root][data-exporting="true"] .post-brand-header { padding: 1.75rem 2rem !important; }
        [data-post-export-root][data-exporting="true"] .post-logo { width: 5rem !important; height: 5rem !important; }
        [data-post-export-root][data-exporting="true"] .post-title { font-size: 2rem !important; line-height: 1.2 !important; }
        [data-post-export-root][data-exporting="true"] .post-tagline { font-size: 1rem !important; }
        [data-post-export-root][data-exporting="true"] .post-range { font-size: 0.875rem !important; }
        [data-post-export-root][data-exporting="true"] .post-legend { padding: 1rem 2rem !important; gap: 1.25rem !important; }
        [data-post-export-root][data-exporting="true"] .post-legend-item { font-size: 0.875rem !important; }
        [data-post-export-root][data-exporting="true"] .post-legend-swatch { width: 2rem !important; height: 0.875rem !important; }
        [data-post-export-root][data-exporting="true"] .post-table { font-size: 0.875rem !important; }
        [data-post-export-root][data-exporting="true"] .post-date-col { width: 9rem !important; padding: 1rem 1.25rem !important; }
        [data-post-export-root][data-exporting="true"] .post-date-weekday { font-size: 1.125rem !important; }
        [data-post-export-root][data-exporting="true"] .post-date-sub { font-size: 0.9375rem !important; }
        [data-post-export-root][data-exporting="true"] .post-court-col { min-width: 20rem !important; padding: 1rem !important; font-size: 1.125rem !important; }
        [data-post-export-root][data-exporting="true"] .post-grid-cell { padding: 1.125rem !important; }
        [data-post-export-root][data-exporting="true"] .post-hour-grid { gap: 0.75rem !important; }
        [data-post-export-root][data-exporting="true"] .post-hour-cell { padding: 0.75rem 0.625rem !important; min-height: 3.75rem !important; border-width: 2px !important; border-radius: 0.625rem !important; }
        [data-post-export-root][data-exporting="true"] .post-hour-time { font-size: 1rem !important; line-height: 1.25 !important; }
        [data-post-export-root][data-exporting="true"] .post-hour-status { font-size: 0.875rem !important; line-height: 1.25 !important; }
        [data-post-export-root][data-exporting="true"] .post-address { font-size: 0.8125rem !important; padding: 1rem 2rem !important; }
      `}</style>
      <div className="w-full max-w-full mx-auto mb-3 flex justify-end">
        <button
          type="button"
          onClick={handleDownloadPng}
          disabled={isExporting}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold text-white shadow-sm transition-colors disabled:opacity-60"
          style={{ background: "linear-gradient(135deg, #2F55FF 0%, #E414D8 100%)" }}
        >
          {isExporting ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Download className="h-4 w-4" />
          )}
          {isExporting ? "Exporting…" : "Download PNG"}
        </button>
      </div>

      <div ref={previewRef} className="w-full max-w-full mx-auto overflow-hidden">
        <div
          className="mx-auto"
          style={
            isExporting
              ? { width: naturalWidth }
              : {
                  width: naturalWidth * fitScale,
                  height: contentHeight ? contentHeight * fitScale : undefined,
                }
          }
        >
          <div
            ref={captureRef}
            className="mx-auto bg-[#F5F7FF] p-4 md:p-6"
            style={{
              width: `${naturalWidth}px`,
              maxWidth: "none",
              transform: isExporting || fitScale >= 1 ? "none" : `scale(${fitScale})`,
              transformOrigin: "top left",
            }}
            data-post-export-root
          >
        <div
          className="bg-white rounded-2xl shadow-lg border-2 border-[#2F55FF]/20 overflow-hidden"
          data-post-card
        >
          {/* Brand header */}
          <div
            className="px-6 py-5 text-white post-brand-header"
            style={{ background: "linear-gradient(135deg, #0B102E 0%, #2F55FF 55%, #E414D8 120%)" }}
          >
            <div className="flex items-center gap-4">
              <img
                src={config.assetPath("logo.png")}
                alt={config.name}
                className="w-16 h-16 rounded-full border-2 border-white/30 object-cover bg-white post-logo"
              />
              <div>
                <h2 className="text-2xl font-signature font-normal text-white tracking-tight drop-shadow-md post-title">
                  {config.name}
                </h2>
                <p className="text-sm text-white/80 mt-0.5 post-tagline">
                  {config.tagline || "Court availability"}
                </p>
                <p className="text-xs text-white/60 mt-1 font-medium post-range">{rangeLabel}</p>
              </div>
            </div>
          </div>

          {/* Legend */}
          <div className="flex flex-wrap gap-4 px-6 py-3.5 border-b-2 border-slate-200 bg-slate-50/80 post-legend">
            {(["available", "booked", "unavailable"]).map((key) => (
              <div key={key} className="flex items-center gap-2 text-sm font-semibold text-slate-700 post-legend-item">
                <span className={`h-3.5 w-7 rounded border post-legend-swatch ${statusStyles[key]}`} />
                {POST_STATUS[key].label}
              </div>
            ))}
          </div>

          {/* Grid — rows: days, columns: courts; 4 hour slots per row */}
          <div className="overflow-x-auto" data-post-scroll>
            <table
              className="w-full border-collapse text-sm post-table"
              style={{ minWidth: `${tableMinWidth}px` }}
            >
              <thead>
                <tr className="border-b-2 border-slate-300">
                  <th className="sticky left-0 z-10 bg-white px-4 py-3 text-left font-bold text-[#0B102E] border-r-2 border-slate-300 w-36 post-date-col">
                    Date
                  </th>
                  {courts.map((court) => (
                    <th
                      key={court.id}
                      className="px-3 py-3 text-center border-r border-slate-200 font-bold text-[#0B102E] text-base post-court-col"
                      style={{ minWidth: `${courtColMinWidth}px` }}
                    >
                      {court.name}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {days.map((day) => {
                  const dateYmd = day.toLocaleDateString("en-CA");
                  const isToday =
                    dateYmd === new Date().toLocaleDateString("en-CA");
                  return (
                    <tr key={dateYmd} className="border-b border-slate-200">
                      <td className="sticky left-0 z-10 bg-white px-4 py-3 border-r-2 border-slate-300 whitespace-nowrap align-top post-date-col">
                        <div className={`font-bold text-base post-date-weekday ${isToday ? "text-[#2F55FF]" : "text-[#0B102E]"}`}>
                          {day.toLocaleDateString("en-US", { weekday: "short" })}
                        </div>
                        <div className="text-sm text-slate-500 font-medium post-date-sub">
                          {day.toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                        </div>
                      </td>
                      {courts.map((court) => (
                        <td
                          key={`${dateYmd}-${court.id}`}
                          className="p-3.5 align-top border-r border-slate-200 post-grid-cell"
                        >
                          <div className="grid grid-cols-4 gap-2.5 post-hour-grid">
                            {hours.map((hour) => renderHourChip(court.id, dateYmd, hour))}
                          </div>
                        </td>
                      ))}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {config.address && (
            <div className="px-6 py-3 text-xs text-slate-500 border-t border-slate-200 text-center post-address">
              {config.address}
            </div>
          )}
        </div>
          </div>
        </div>
      </div>
    </div>
  );
}
